INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('7fa3579bd69939333ddc0f0633', 'faq', 'home-1', 0, 'f8e415f92e8dd3e55a0afe1f65', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('f8e415f92e8dd3e55a0afe1f65', '7fa3579bd69939333ddc0f0633', '{"question":"What services does Infoane provide?","answer":"We are an IT consulting and software development company. We build custom web, mobile and back-office applications, migrate workloads to AWS, Azure and Google Cloud, modernize legacy systems, build data platforms and analytics, implement AI and automation, and provide dedicated engineering teams that work alongside your in-house staff.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('dcc29f24f4d439c90a3c6fef7b', 'faq', 'home-2', 1, '17cdf8f5d22592467a25c50413', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('17cdf8f5d22592467a25c50413', 'dcc29f24f4d439c90a3c6fef7b', '{"question":"How much does custom software development cost?","answer":"Cost depends on scope, integrations and compliance requirements, so we do not quote a single number up front. A focused MVP typically runs [$XX,000–$XXX,000] and a multi-team enterprise programme is priced per sprint or per team. Our paid discovery phase ends with a written scope and a costed delivery plan, so you can commit to the build with a real number rather than an estimate.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('4b64d5438b4bad99552ecc9128', 'faq', 'home-3', 2, '84e8a45595f080899a7f8a8b71', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('84e8a45595f080899a7f8a8b71', '4b64d5438b4bad99552ecc9128', '{"question":"What engagement models do you offer?","answer":"Three: fixed-scope projects for well-defined deliverables, time-and-materials for evolving product work, and dedicated teams billed monthly for long-running engagements. Most clients start with a short discovery engagement and then pick the model that fits what discovery found.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('7b8e50a3e9bdd281dec1b53753', 'faq', 'home-4', 3, 'f250d68ac85a157f2a2340a4d8', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('f250d68ac85a157f2a2340a4d8', '7b8e50a3e9bdd281dec1b53753', '{"question":"How quickly can a team start?","answer":"Discovery usually begins within [1–2] weeks of a signed agreement. A full delivery team is typically staffed and onboarded within [2–4] weeks, depending on the specialisms involved.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('cd8715bb01d7d44141dcb76294', 'faq', 'home-5', 4, '0823eed8544e16d18253a00fb4', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('0823eed8544e16d18253a00fb4', 'cd8715bb01d7d44141dcb76294', '{"question":"Who owns the code and the intellectual property?","answer":"You do. Our contracts assign all IP, source code and documentation to you on payment, and everything lives in your repositories and cloud accounts from the first commit — not ours. You are never dependent on us to keep the system running.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('4a794deecce05f2a51bbf871e8', 'faq', 'home-6', 5, 'e1cbce6daa8d1b43b207d9a9ae', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('e1cbce6daa8d1b43b207d9a9ae', '4a794deecce05f2a51bbf871e8', '{"question":"How do you handle security and compliance?","answer":"We work under NDA, follow least-privilege access on client systems, and run secure development practices including code review, dependency scanning and secrets management. We hold [ISO 27001 / SOC 2 Type II] and have delivered under [GDPR, HIPAA, PCI-DSS] requirements. We can work inside your own security tooling and review process.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('b5a7ac59ced5fca00d87bcc620', 'faq', 'home-7', 6, '9923e434d11c00908759921b37', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('9923e434d11c00908759921b37', 'b5a7ac59ced5fca00d87bcc620', '{"question":"Do you work with our existing in-house engineers?","answer":"Yes, and that is most of what we do. Our teams join your sprint rituals, your repository and your code standards. We are also happy to be measured on how well your team can maintain the system after we leave — documentation and handover are part of every engagement.","placement":"home"}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('e73ae6b46b8936e929a6c27ddc', 'pillar', 'pillar-01', 0, '2e35f40db6dd881733e4dbbe7b', NULL, 'published', 1787137021049, 1787137021049, NULL);
