INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('3af31efe704c0a07aa8da40e94', 'a87e16ce379aed87fb846d0cf4', '{"name":"Dedicated team","tagline":"Best when the roadmap keeps moving","price":"[$X,XXX]","unit":"per person / month","summary":"Named engineers embedded in your team, working your process in your repository, scaling up or down as scope changes.","includes":["Named candidates you interview","Minimum [4]-hour overlap with your day","Work tracked in your own backlog","[30] days'' notice to change team size"],"popular":false}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('32263f75e1b0f910d10e3b8b93', 'page', 'home', 0, 'f1ac6935384d52da48c2b04ea5', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('f1ac6935384d52da48c2b04ea5', '32263f75e1b0f910d10e3b8b93', '{"metaTitle":"IT Consulting & Custom Software Development Company","metaDescription":"Infoane is an IT consulting and custom software development company helping enterprises modernize legacy systems, move to the cloud, and ship software faster.","heading":"IT consulting and custom software for modern enterprises","intro":["We modernise the systems your business runs on, move them to the cloud, and build the software your competitors cannot buy off-the-shelf. Senior engineers, honest scoping, and a working demo every two weeks."],"sections":[{"eyebrow":"","title":"Platforms and clouds we build on","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"platforms","label":"Platform strip"},{"eyebrow":"","title":"How an engagement works","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"pillars","label":"Engagement pillars"},{"eyebrow":"What we do","title":"Software and cloud services, end to end","lead":"Six practices covering the whole lifecycle — from the first architecture decision to running the system at scale. Most clients start with one and expand.","ctaLabel":"All services","bullets":[],"footnote":"","key":"services","label":"Services grid"},{"eyebrow":"How we work","title":"A delivery process you can hold us to","lead":"Most failed projects fail in the first month, on assumptions nobody wrote down. This is the sequence we use so that does not happen.","ctaLabel":"","bullets":[],"footnote":"","key":"process","label":"How we work (tabs)"},{"eyebrow":"Industries","title":"Domain knowledge, not just engineering","lead":"Regulated industries do not need developers who learn the domain on your budget. These are the sectors we have shipped in repeatedly.","ctaLabel":"","bullets":[],"footnote":"","key":"industries","label":"Industries grid"},{"eyebrow":"Technology","title":"We work in the stack you already run","lead":"We pick the boring, proven tool unless there is a specific reason not to — a stack you can still hire for in five years matters more than one that is exciting this quarter. You inherit the maintenance, not us.","ctaLabel":"See our full stack","bullets":["Managed services over self-hosted, unless there is a reason","Where two options are close, your team’s stack wins","Nothing load-bearing without a maintained release history"],"footnote":"This reflects what our clients run, not the limit of what we will work on — and we would rather tell you we are not a fit than learn your platform on your budget.","key":"technologies","label":"Tech stack"},{"eyebrow":"Success stories","title":"Results our clients can point at","lead":"Described the way we would describe them to your board: what was broken, what we built, and the number that changed.","ctaLabel":"All case studies","bullets":[],"footnote":"","key":"work","label":"Case studies"},{"eyebrow":"Client feedback","title":"What it is like to work with us","lead":"Ask any of our references the same question you would ask us: what happened when something went wrong?","ctaLabel":"","bullets":[],"footnote":"","key":"testimonials","label":"Testimonials"},{"eyebrow":"Engagement models","title":"Three ways to work with us","lead":"Most clients start with discovery and then pick the shape that fits what discovery found. You are never locked into the first choice.","ctaLabel":"Schedule a call","bullets":[],"footnote":"","key":"engagement","label":"Engagement models"},{"eyebrow":"FAQ","title":"Your questions, answered","lead":"If yours is not here, ask it on the call — we would rather answer it before you sign than after.","ctaLabel":"Contact us","bullets":[],"footnote":"","key":"faq","label":"FAQ"},{"eyebrow":"Start your journey","title":"Let’s start building something great together","lead":"Book a free {consultationLength} consultation. You will talk to an engineer, not an account manager, and you will leave with a concrete opinion on your options — whether or not you hire us.","ctaLabel":"","bullets":[],"footnote":"","key":"contact","label":"Closing CTA"}],"ctaBand":{"heading":"Tell us what is slowing your systems down","body":"Book a free {consultationLength} consultation. You will talk to an engineer, not an account manager, and you will leave with a concrete opinion on your options — whether or not you hire us."},"labels":{"hero.cadenceLabel":"Sprint cadence","hero.cadenceValue":"2 weeks","hero.demoLabel":"Working demo each sprint","hero.demoValue":"100%","hero.ipLabel":"IP & source code","hero.ipValue":"Yours on payment","services.itemCta":"Explore","process.stageWord":"Stage","process.statusComplete":"Complete","process.statusActive":"Active","process.statusQueued":"Queued","technologies.askHeading":"Not on the list?","technologies.askCta":"Ask us","work.challengeLabel":"Challenge","work.outcomeLabel":"Outcome","work.itemCta":"Read the full case study","testimonials.extraTitle":"We would rather be measured on whether your team can maintain the system after we leave.","testimonials.extraBody":"Documentation, tests and a recorded walkthrough are part of every engagement — not an upsell at the end.","engagement.popularBadge":"Most chosen","contact.replyNote":"Replies within {responseTime}","contact.ndaNote":"NDA on request"},"hero":{"headline":"IT consulting and custom software for modern enterprises","highlight":"custom software","subhead":"We modernise the systems your business runs on, move them to the cloud, and build the software your competitors cannot buy off-the-shelf. Senior engineers, honest scoping, and a working demo every two weeks.","primaryCta":"Get started","secondaryCta":"Explore services","note":"A free {consultationLength} call with an engineer who has shipped this before. No sales script.","cardTitle":"Your first engagement","cardItems":["Stakeholder interviews and system audit","Target architecture, with trade-offs","Written scope, timeline and costed plan","Yours to keep — even if you stop there"]}}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('987b0443cd1dabff3921bb3046', 'page', 'about', 1, 'abdcb4ee9472769d9c30b5c7a7', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('abdcb4ee9472769d9c30b5c7a7', '987b0443cd1dabff3921bb3046', '{"metaTitle":"About Us","metaDescription":"Infoane is an IT consulting and software development company. Meet the team, how we work, and the principles we hold to on every engagement.","heading":"An engineering firm, not a body shop","intro":["Infoane was founded in [YYYY] to do consulting work the way its founders wanted to be treated as clients: senior people on the engagement, an honest opinion when the brief is wrong, and a system the client can run without us.","Today we are [XX] engineers, QA specialists and DevOps practitioners working with [industries you serve] across [regions you serve]. We are large enough to staff a full delivery team and small enough that the people who scope your project are the people who build it."],"sections":[{"eyebrow":"How we operate","title":"Six things we hold to","lead":"These are commitments, not values on a wall. Hold us to them — and tell us when we slip.","ctaLabel":"","bullets":[],"footnote":"","key":"principles","label":"Principles"},{"eyebrow":"Leadership","title":"Who you will actually be working with","lead":"The people who scope your engagement stay on it. No handoff to a delivery team you have never met.","ctaLabel":"","bullets":[],"footnote":"","key":"leadership","label":"Leadership"},{"eyebrow":"Timeline","title":"How we got here","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"milestones","label":"Timeline"},{"eyebrow":"Where we are","title":"Our offices","lead":"Delivery teams work with an overlap to your business hours — the location matters less than the overlap, and we staff for the overlap.","ctaLabel":"","bullets":[],"footnote":"","key":"offices","label":"Offices"}],"ctaBand":{"heading":"Tell us what is slowing your systems down","body":"Book a free {consultationLength} consultation. You will talk to an engineer, not an account manager, and you will leave with a concrete opinion on your options — whether or not you hire us."},"labels":{},"principles":[{"title":"The senior people are on the work","body":"The engineer who scopes your project is on the delivery team. We do not win work with architects and staff it with juniors."},{"title":"We will tell you not to build it","body":"If configuration solves it, or if the honest answer is that the project is not worth its cost, you will hear that from us before you spend the budget."},{"title":"You own everything","body":"Code, infrastructure and documentation live in your accounts from the first commit, and IP transfers on payment. No dependency on us by design."},{"title":"Estimates are evidence-based","body":"Numbers come out of a discovery phase, not out of a sales meeting. When we are uncertain we give you a range and tell you what would narrow it."},{"title":"Bad news travels fast","body":"Slippage and risk surface in the next status update, not at the deadline. There is no version of this that improves with delay."},{"title":"We optimise for handover","body":"Documentation, tests and pairing are part of delivery. If you take the system in-house afterwards, we did our job."}],"leadership":[{"name":"[Full name]","role":"[Founder & CEO]","bio":"[Two sentences: relevant background, years in the field, what they own here. Link the LinkedIn profile.]","linkedin":"https://www.linkedin.com/in/[handle]"},{"name":"[Full name]","role":"[CTO / Head of Delivery]","bio":"[Two sentences of real background.]","linkedin":"https://www.linkedin.com/in/[handle]"},{"name":"[Full name]","role":"[Head of Engineering]","bio":"[Two sentences of real background.]","linkedin":"https://www.linkedin.com/in/[handle]"}],"milestones":[{"year":"[YYYY]","event":"[Company founded in [city]]"},{"year":"[YYYY]","event":"[First enterprise client / first office opened]"},{"year":"[YYYY]","event":"[ISO 27001 certification achieved]"},{"year":"[YYYY]","event":"[Team reached [XX] engineers]"}]}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('78f81f37fb88e69050459644c9', 'page', 'services', 2, '73699bd34f44a3acc74a47308c', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('73699bd34f44a3acc74a47308c', '78f81f37fb88e69050459644c9', '{"metaTitle":"IT Services & Software Development Services","metaDescription":"Our services: custom software development, cloud migration and DevOps, legacy modernization, data engineering, AI automation and dedicated development teams.","heading":"What we do","intro":["Six practices covering the full lifecycle of a system — from the first architecture decision to running it at scale in production.","Most clients start with one and expand. If you are not sure which applies, describe the problem and we will tell you, including when the answer is that you do not need us."],"sections":[{"eyebrow":"Our practices","title":"Services in detail","lead":"Each page covers the symptoms that lead clients here, how we approach the work, what you receive, and the technologies involved.","ctaLabel":"","bullets":[],"footnote":"","key":"all-services","label":"Services list"},{"eyebrow":"How we work","title":"A delivery process you can hold us to","lead":"Most failed projects fail in the first month, on assumptions nobody wrote down. This is the sequence we use to make sure that does not happen.","ctaLabel":"","bullets":[],"footnote":"","key":"process","label":"Delivery process"},{"eyebrow":"When to call us","title":"You probably need this if…","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"detail-signals","label":"Service page — “when to call us”"},{"eyebrow":"How we work","title":"","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"detail-approach","label":"Service page — approach"},{"eyebrow":"Deliverables","title":"What you actually receive","lead":"Artefacts, not activity. Everything here is something you keep, and something you could hand to another supplier.","ctaLabel":"","bullets":[],"footnote":"","key":"detail-deliverables","label":"Service page — deliverables"},{"eyebrow":"FAQ","title":"","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"detail-faq","label":"Service page — FAQ"},{"eyebrow":"Related services","title":"Often needed alongside this","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"detail-related","label":"Service page — related"}],"ctaBand":{"heading":"Not sure which service you need?","body":"Describe the problem rather than the solution. We will tell you which of these applies — or that configuration solves it and you should keep your budget."},"labels":{}}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('147d65ebf8508c44a936c32112', 'page', 'industries', 3, 'ab04d6b2823fcb8223e0eb1013', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('ab04d6b2823fcb8223e0eb1013', '147d65ebf8508c44a936c32112', '{"metaTitle":"Industries We Serve","metaDescription":"IT consulting and software development for financial services, healthcare, manufacturing, logistics, retail, SaaS and energy — with the compliance context.","heading":"Industries we serve","intro":["Regulated industries do not need engineers who learn the domain on the client''s budget. These are the sectors where we have shipped repeatedly and already know which constraints are real."],"sections":[{"eyebrow":"Sector experience","title":"Where we have delivered","lead":"Each of these carries constraints that shape architecture rather than decorate it — regulatory scope, uptime expectations, and the systems you cannot replace.","ctaLabel":"","bullets":[],"footnote":"","key":"sectors","label":"Sector list"}],"ctaBand":{"heading":"Your sector not listed?","body":"Domain knowledge transfers further than most agencies admit — the constraints that matter are usually regulatory, data-shaped or uptime-driven rather than industry-specific. Describe yours and we will tell you honestly whether we are a fit."},"labels":{}}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('c215f6892d549bfda01c87710c', 'page', 'technology', 4, '51a91ea14ac4fd1d3e02076b0c', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('51a91ea14ac4fd1d3e02076b0c', 'c215f6892d549bfda01c87710c', '{"metaTitle":"Our Technology Stack","metaDescription":"The technologies we build with: React, Next.js, .NET, Node.js, Python, AWS, Azure, Kubernetes, Snowflake, dbt and more — and how we choose between them.","heading":"Technology we build with","intro":["We pick the boring, proven tool unless there is a specific reason not to. A stack you can still hire for in five years matters more than one that is exciting this quarter — you inherit the maintenance, not us.","Below is what we work in most. If your stack is not listed, ask: the list reflects what clients run, not the limit of what we will work on."],"sections":[{"eyebrow":"Our stack","title":"What we build with","lead":"Grouped by layer, with a note on when each one earns its place.","ctaLabel":"","bullets":[],"footnote":"","key":"stack","label":"Stack by layer"},{"eyebrow":"Selection criteria","title":"How we choose between them","lead":"Technology choices outlive the people who make them. These are the tie-breakers we apply.","ctaLabel":"","bullets":[],"footnote":"","key":"how-we-choose","label":"Selection criteria"},{"eyebrow":"Put to work","title":"Where we apply it","lead":"Each service page lists the specific technologies that engagement typically involves.","ctaLabel":"","bullets":[],"footnote":"","key":"services-using-stack","label":"Services using the stack"}],"ctaBand":{"heading":"Working in a stack we have not listed?","body":"Ask. The list reflects what our clients run, not the limit of what we will work on — and we would rather tell you we are not the right fit than learn your platform on your budget."},"labels":{},"principles":[{"title":"Managed over self-hosted","body":"We run a database or a cluster yourself only when there is a cost, latency or compliance reason. Undifferentiated operations work is not a good use of your budget."},{"title":"Your team''s stack wins ties","body":"Where two options are close, we pick the one your engineers already know. Handover is part of the design."},{"title":"No framework of the month","body":"New dependencies need a reason beyond novelty, and anything load-bearing has to have a maintained release history."}],"techGroups":[{"group":"Frontend","body":"Component-driven interfaces with server rendering where SEO or first-load performance matters.","items":["React","Next.js","TypeScript","Tailwind CSS","React Native","Flutter"]},{"group":"Backend","body":"Long-lived server platforms chosen to match your team''s existing skills wherever possible.","items":[".NET","Node.js","Java","Python","Go","FastAPI"]},{"group":"Cloud & DevOps","body":"Infrastructure as code, reproducible environments and pipelines that deploy on merge.","items":["AWS","Azure","Google Cloud","Kubernetes","Terraform","Docker","GitHub Actions"]},{"group":"Data","body":"Warehouses and pipelines with tested, version-controlled metric definitions.","items":["Snowflake","Databricks","BigQuery","PostgreSQL","SQL Server","dbt","Airflow","Kafka"]},{"group":"AI","body":"Retrieval, evaluation and human-in-the-loop review around frontier and self-hosted models.","items":["Claude","OpenAI","LangChain","pgvector","Pinecone"]},{"group":"Quality & Observability","body":"Automated testing and production visibility, treated as delivery scope rather than an extra.","items":["Playwright","Jest","xUnit","pytest","Prometheus","Grafana","OpenTelemetry"]}]}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('e97b3b6335b0c5774fe71a8bb1', 'page', 'case-studies', 5, 'ef4afe39c455fd9c7bf25e6174', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('ef4afe39c455fd9c7bf25e6174', 'e97b3b6335b0c5774fe71a8bb1', '{"metaTitle":"Case Studies & Client Results","metaDescription":"How we helped clients modernize legacy systems, migrate to the cloud and ship faster — the problem, the approach and the measurable outcome in each case.","heading":"Case studies","intro":["Each of these is described the way we would describe it to your board: what was broken, what we did, and what changed as a result. Where a client cannot be named, the sector and the numbers are still real."],"sections":[{"eyebrow":"Engagements","title":"Problem, approach, result","lead":"No hero narratives. What was broken, what we did about it, and the number that changed.","ctaLabel":"","bullets":[],"footnote":"","key":"studies","label":"Engagement list"},{"eyebrow":"Client feedback","title":"What it is like to work with us","lead":"Ask any of our references the same question you would ask us: what happened when something went wrong?","ctaLabel":"","bullets":[],"footnote":"","key":"testimonials","label":"Testimonials"},{"eyebrow":"Services involved","title":"The work behind these results","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"services-behind","label":"Services involved"}],"ctaBand":{"heading":"Want to talk to one of these clients?","body":"We will put you in touch with a reference whose problem resembled yours. Ask them what happened when something went wrong — that is the answer worth having."},"labels":{"testimonials.extraTitle":"We would rather be measured on whether your team can maintain the system after we leave.","testimonials.extraBody":"Documentation, tests and a recorded walkthrough are part of every engagement — not an upsell at the end."}}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('ff32012056d8eab88f0c81583b', 'page', 'careers', 6, 'b8a0b1793ff0a98df6af272461', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('b8a0b1793ff0a98df6af272461', 'ff32012056d8eab88f0c81583b', '{"metaTitle":"Careers","metaDescription":"Work at Infoane. Open engineering, QA and DevOps roles, how our hiring process works, and what to expect from working here.","heading":"Build systems that stay built","intro":["We hire people who want to own outcomes rather than tickets. That means talking to clients, disagreeing with a brief when it is wrong, and writing the documentation you would want to inherit."],"sections":[{"eyebrow":"Open roles","title":"Where we are hiring","lead":"If none of these fit but you think you should be here, write to us anyway and say why.","ctaLabel":"","bullets":[],"footnote":"","key":"openings","label":"Open roles"},{"eyebrow":"What we offer","title":"The practical details","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"benefits","label":"Benefits"},{"eyebrow":"Hiring process","title":"What to expect, in order","lead":"Four steps, and you hear back at each one. We know what it is like to be left waiting.","ctaLabel":"","bullets":[],"footnote":"","key":"hiring-process","label":"Hiring process"}],"ctaBand":{"heading":"Not seeing your role?","body":"Tell us what you want to work on and what you have shipped. We read every application, and we reply either way."},"labels":{},"benefits":[{"title":"[Remote-first / hybrid]","body":"[Describe the actual working model, including office expectations.]"},{"title":"[Learning budget]","body":"[Annual amount and what it covers.]"},{"title":"[Health cover]","body":"[What is covered, and for whom.]"},{"title":"[Paid leave]","body":"[Days per year, plus policy on public holidays.]"}],"hiringProcess":[{"step":"01","title":"Application review","body":"A person reads it. You hear back either way within [one week]."},{"step":"02","title":"Intro conversation","body":"[30] minutes on your background and what you want next."},{"step":"03","title":"Technical conversation","body":"A discussion of real problems — no whiteboard algorithm puzzles."},{"step":"04","title":"Offer","body":"Written offer with the salary band stated up front."}],"openings":[{"title":"[Senior Full-Stack Engineer]","location":"[City / Remote]","type":"[Full-time]","summary":"[Two lines on the role and the stack.]"},{"title":"[DevOps / Platform Engineer]","location":"[City / Remote]","type":"[Full-time]","summary":"[Two lines on the role and the stack.]"},{"title":"[QA Automation Engineer]","location":"[City / Remote]","type":"[Full-time]","summary":"[Two lines on the role and the stack.]"}]}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('9033f28699ff6c20f338318751', 'page', 'contact', 7, '65eb64dcc7230c3bb74fc43dfc', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('65eb64dcc7230c3bb74fc43dfc', '9033f28699ff6c20f338318751', '{"metaTitle":"Contact Us","metaDescription":"Talk to an engineer, not an account manager. Email or call Infoane to book a free consultation about your software, cloud or data project.","heading":"Tell us what is slowing your systems down","intro":["Book a free consultation and you will speak to an engineer who has shipped work like yours. You will leave with a concrete opinion on your options, whether or not you hire us."],"sections":[{"eyebrow":"Direct lines","title":"How to reach us","lead":"Email gets the fastest considered answer; the phone gets the fastest answer. Both reach a person who can talk about the work.","ctaLabel":"","bullets":[],"footnote":"","key":"reach-us","label":"Direct lines"},{"eyebrow":"Offices","title":"Where we are","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"offices","label":"Offices"},{"eyebrow":"Or start with a service","title":"Know what you need already?","lead":"Go straight to the relevant service page — each one lists what the engagement involves and what you receive.","ctaLabel":"","bullets":[],"footnote":"","key":"which-service","label":"Start with a service"}],"ctaBand":{"heading":"Tell us what is slowing your systems down","body":"Book a free {consultationLength} consultation. You will talk to an engineer, not an account manager, and you will leave with a concrete opinion on your options — whether or not you hire us."},"labels":{},"expectations":["A reply within [one business day]","An NDA before you share anything sensitive, on request","No obligation, and no sales sequence afterwards"]}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('9798bacebd0fa784fe13c80fbb', 'page', 'privacy-policy', 8, 'b1abc7980dd515fda1714b2c9c', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('b1abc7980dd515fda1714b2c9c', '9798bacebd0fa784fe13c80fbb', '{"metaTitle":"Privacy Policy","metaDescription":"How Infoane collects, uses and protects personal information submitted through this website.","heading":"Privacy Policy","intro":["This page is a placeholder structure and is excluded from search engines until the final text is in place."],"sections":[{"eyebrow":"Draft structure","title":"Sections this policy needs to cover","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"sections","label":"Policy sections"}],"ctaBand":{"heading":"Tell us what is slowing your systems down","body":"Book a free {consultationLength} consultation. You will talk to an engineer, not an account manager, and you will leave with a concrete opinion on your options — whether or not you hire us."},"labels":{},"blocks":[{"title":"Who we are","body":"[Legal entity name, registered address, and the contact details of the person or team responsible for data protection enquiries. Name your Data Protection Officer if you are required to have one.]"},{"title":"What information we collect","body":"[List each category: information submitted through forms or email, information collected automatically such as IP address and browser type, and anything collected via cookies or analytics. Be specific — vague categories are the most common weakness in a policy.]"},{"title":"Why we collect it and our lawful basis","body":"[For each purpose — answering enquiries, delivering services, recruitment, marketing — state the purpose and the lawful basis you rely on (consent, contract, legitimate interests, legal obligation).]"},{"title":"Cookies and analytics","body":"[Which cookies you set, which are strictly necessary, and which require consent. Name your analytics provider and link its policy. If you deploy anything beyond strictly necessary cookies, you need a consent banner before it loads — the site does not have one yet.]"},{"title":"Who we share information with","body":"[Named categories of processors: hosting, email, CRM, analytics. State whether data is transferred outside its country of origin and what safeguards apply.]"},{"title":"How long we keep it","body":"[Retention period per category, and what triggers deletion.]"},{"title":"Your rights","body":"[Access, correction, deletion, portability, objection, and withdrawal of consent — plus how to exercise them, how quickly you will respond, and which regulator a visitor can complain to.]"},{"title":"Security","body":"[The measures you actually take: encryption in transit and at rest, access control, staff training, breach notification process. Do not describe controls you do not have.]"},{"title":"Changes to this policy","body":"[How you notify people about changes, and the date this version took effect.]"}]}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
INSERT INTO content_items (id, collection, slug, sort_order, published_revision_id, draft_revision_id, status, created_at, updated_at, created_by) VALUES ('1f19d4c20577eee7135c48d1f0', 'page', 'terms', 9, 'fd5ade115dc7f13f3fee4c7fa2', NULL, 'published', 1787137021049, 1787137021049, NULL);
INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('fd5ade115dc7f13f3fee4c7fa2', '1f19d4c20577eee7135c48d1f0', '{"metaTitle":"Terms of Service","metaDescription":"Terms governing use of the Infoane website, including permitted use, intellectual property and limitation of liability.","heading":"Terms of Service","intro":["This page is a placeholder structure and is excluded from search engines until the final text is in place."],"sections":[{"eyebrow":"Draft structure","title":"Sections these terms need to cover","lead":"","ctaLabel":"","bullets":[],"footnote":"","key":"sections","label":"Terms sections"}],"ctaBand":{"heading":"Tell us what is slowing your systems down","body":"Book a free {consultationLength} consultation. You will talk to an engineer, not an account manager, and you will leave with a concrete opinion on your options — whether or not you hire us."},"labels":{},"blocks":[{"title":"Acceptance of terms","body":"[State that using the site constitutes acceptance, and how you notify visitors of changes.]"},{"title":"Use of this website","body":"[Permitted and prohibited use: no scraping beyond what robots.txt allows, no attempts to disrupt the service, no misuse of contact channels.]"},{"title":"Intellectual property","body":"[Who owns the site content, trade marks and logos, and what visitors may quote or reproduce. Note separately that client project IP transfers to the client under your services agreement.]"},{"title":"Content accuracy","body":"[Site content is informational; nothing on it is an offer or a professional recommendation for a specific situation.]"},{"title":"Third-party links","body":"[You are not responsible for the content or practices of sites you link to.]"},{"title":"Limitation of liability","body":"[The limitation you and your counsel decide on, within what the applicable jurisdiction permits.]"},{"title":"Governing law","body":"[Which jurisdiction''s law applies and where disputes are heard.]"},{"title":"Contact","body":"[Where to send questions about these terms.]"}]}', 'published', 'Seeded from src/content', NULL, 1787137021049, NULL, NULL, NULL, 1787137021049);
